    "faqQ1": "Match cut nedir?",
    "faqA1": "Match cut, bir ifadenin veya kelimenin hızlı ve senkronize bir şekilde sahne değiştirerek (kesilerek) gösterildiği güçlü bir kurgu tekniğidir.",
