    "legalLastUpdated": "Son güncelleme:",
    "legalDataTitle": "2. Veri Toplama ve Firebase Bulut Senkronizasyonu",
    "legalDataText": "Yalnızca hizmetin çalışması için gereken verileri toplarız: oturum açtığınızda e-posta gibi Firebase kimlik doğrulama bilgileri, proje metadataları, taslaklar, tercihler, ödeme veya ödül kayıtları, tanılama bilgileri ve kaydetmeyi seçtiğiniz metinler veya ayarlar. Firebase kimlik doğrulama, depolama ve bulut senkronizasyonu için kullanılır; böylece projeleriniz ve ayarlarınız cihazlar arasında geri yüklenebilir. Üretilen videolar geçici dışa aktarma dosyalarıdır ve üretim veya indirme tamamlandıktan sonra silinir; kişisel verileri satmayız ve videoları model eğitimi için kullanmayız.",
    "legalTermsTitle": "3. Hizmet Şartları",
    "legalTermsText": "AnimationMaker'ı yalnızca sahibi olduğunuz veya kullanma izniniz bulunan yasal içerikler için kullanabilirsiniz. Zararlı, yasa dışı, ihlal edici, kötüye kullanım içeren, aldatıcı veya gizliliği ihlal eden içerik üretmeyin. Kullanıcıları korumak, yasalara uymak veya bu şartları uygulamak için hesapları sınırlandırabilir veya askıya alabilir, senkronize verileri kaldırabilir ya da hizmet vermeyi reddedebiliriz.",
    "legalContactTitle": "4. Çerezler, Onay ve Haklarınız",
    "legalContactText": "Zorunlu çerezler ve yerel depolama uygulamanın, güvenliğin, kimlik doğrulamanın ve onay tercihlerinin çalışmasını sağlar. İsteğe bağlı analiz veya reklam teknolojileri yalnızca onay ayarlarınız izin verdiğinde kullanılır. AB/UK kullanıcıları erişim, düzeltme, silme, taşınabilirlik, kısıtlama veya itiraz talep edebilir. Kaliforniya ve uygun diğer ABD eyaletlerindeki kullanıcılar erişim, silme, düzeltme ve satış/paylaşım dışına çıkma talep edebilir; kişisel veri satmayız.",
    "legalRefundTitle": "5. İadeler ve İletişim",
    "legalRefundText": "Dijital satın alımlar, krediler ve abonelikler ödeme tamamlandıktan hemen sonra teslim edilir. AB kullanıcıları hemen teslimat istediklerinde, dijital içerik sağlandıktan sonra yasal cayma hakkının kaybedilebileceğini kabul eder. Hukuki, gizlilik, iade, silme veya DMCA talepleri için legal@animationmaker.app adresine yazın.",
    "legalIntroText": "AnimationMaker, Avrupa Birliği ve Amerika Birleşik Devletleri kullanıcıları için işletilir. Uygun olduğu ölçüde GDPR/UK GDPR, ePrivacy, CCPA/CPRA, COPPA, DMCA ve tüketici koruma kurallarını dikkate alırız. Bu bildirim şeffaflık içindir ve hukuki danışmanlık değildir.",
