    "faqTitle": "常见问题解答",
    "faqQ1": "什么是 Match Cut（匹配剪辑）？",
    "faqA1": "Match Cut 是一种经典的电影级剪辑手法，通过在保持核心文字/主题连贯的同时快速切换同步画面，形成极强视觉冲击力。",
    "faqQ2": "生成一个视频需要多久？",
    "faqA2": "取决于画质和效果复杂度，通常仅需 15-30 秒即可在浏览器中渲染完毕。",
    "faqQ3": "我可以将生成的视频用于商业项目吗？",
    "faqA3": "当然可以！您在 AnimationMaker 生成的所有视频均可免费商用，免版税困扰。",
    "faqQ4": "支持哪些视频比例格式？",
    "faqA4": "目前原生支持 YouTube 适用的横屏 (16:9) 以及抖音/TikTok/Shorts 适用的竖屏 (9:16)。",
    "footerDesc": "基于浏览器的专业视频动画制作工具。",
    "footerRights": "保留所有权利。",
    "legalLastUpdated": "最近更新时间：",
    "legalDataTitle": "2. 数据收集与 Firebase 云端同步",
    "legalDataText": "我们仅收集维持服务运行所必需的数据：登录时的 Firebase 认证信息、项目元数据、草稿设置和偏好配置。所有生成的视频均为临时渲染文件，下载完成后即行销毁，我们绝不出售个人数据或用于模型训练。",
    "legalTermsTitle": "3. 服务使用条款",
    "legalTermsText": "您仅可使用 AnimationMaker 创作合法合规且您享有合法权利的内容。严禁利用本服务制作传播任何违法、侵权、有害或欺诈信息。",
    "legalContactTitle": "4. Cookie、授权与用户权益",
    "legalContactText": "必要 Cookie 用于保障系统安全与账号登录。非必要分析工具仅在您授权同意后方可启用。",
    "legalRefundTitle": "5. 退款政策与联系方式",
    "legalRefundText": "数字资产与会员服务在支付成功后立即交付。如需任何商务咨询、退款或数据删除请求，请邮件联系 legal@animationmaker.app。",
    "legalIntroText": "AnimationMaker 面向全球创作者提供服务，严格遵守 GDPR、CCPA 等全球数据隐私安全保护合规要求。",
