    "faqA2": "設定にもよりますが、ブラウザ上で直接レンダリングされ、通常15〜30秒ほどで完成します。",
    "faqQ3": "商用利用は可能ですか？",
    "faqA3": "はい。作成された動画は個人利用・商用利用を問わず、ロイヤリティフリーでご活用いただけます。",
    "faqQ4": "対応している動画サイズは？",
    "faqA4": "YouTubeに適した横型(16:9)と、TikTok/Reels/Shortsに最適な縦型(9:16)に対応しています。",
