    "faqTitle": "คำถามที่พบบ่อย (FAQ)",
    "faqQ1": "Match Cut คืออะไร?",
    "faqA1": "Match Cut คือเทคนิคการตัดต่อภาพยนตร์ที่ตัดสลับฉากต่างๆ อย่างรวดเร็วและต่อเนื่อง โดยรักษาสิ่งที่เป็นจุดสนใจหรือข้อความหลักให้อยู่ตำแหน่งเดิม",
    "faqQ2": "การสร้างวิดีโอใช้เวลานานแค่ไหน?",
    "faqA2": "ขึ้นอยู่กับการตั้งค่าของคุณ โดยทั่วไปจะใช้เวลาเพียง 15-30 วินาทีในการประมวลผลบนเบราว์เซอร์",
    "faqQ3": "สามารถนำวิดีโอไปใช้ในเชิงพาณิชย์ได้หรือไม่?",
    "faqA3": "ได้แน่นอน วิดีโอทั้งหมดที่คุณสร้างสามารถนำไปใช้ในงานส่วนตัวและงานเชิงพาณิชย์ได้โดยไม่มีค่าลิขสิทธิ์เพิ่มเติม",
    "faqQ4": "รองรับอัตราส่วนวิดีโอขนาดใดบ้าง?",
    "faqA4": "รองรับทั้งแนวนอน (16:9) สำหรับ YouTube และแนวตั้ง (9:16) สำหรับ TikTok, Shorts และ Reels",
    "footerDesc": "เครื่องมือสร้างสรรค์และตัดต่อวิดีโอระดับมืออาชีพบนเว็บเบราว์เซอร์",
