    "legalDataTitle": "2. การรวบรวมข้อมูลและการซิงก์คลาวด์ Firebase",
    "legalDataText": "เราเก็บเฉพาะข้อมูลที่จำเป็นต่อการใช้งาน เช่น ข้อมูลการเข้าสู่ระบบ Firebase และการตั้งค่าโปรเจกต์ วิดีโอที่สร้างขึ้นเป็นไฟล์ชั่วคราวและจะถูกลบหลังจากดาวน์โหลดเสร็จสิ้น",
