    "legalTermsText": "คุณสามารถใช้งาน AnimationMaker สำหรับเนื้อหาที่ถูกกฎหมายเท่านั้น ห้ามสร้างเนื้อหาที่ละเมิดลิขสิทธิ์หรือสร้างความเสียหายแก่ผู้อื่น",
    "legalContactTitle": "4. คุกกี้และความเป็นส่วนตัวของคุณ",
